#include "linear_dae.hpp"
#include "runtime/lazy_module.hpp"
#include "runtime/thread_budget.hpp"
#include <cmath>
#include <cstring>
namespace penta::dae {
namespace {
struct Host {const std::shared_ptr<std::atomic_bool>& cancellation;const std::function<void(std::size_t)>& charge;std::exception_ptr failure;
    static int cancelled(void* raw){const auto& h=*static_cast<Host*>(raw);return h.cancellation&&h.cancellation->load();}
    static int account(void* raw,uint64_t count,char* error,uint64_t capacity)noexcept{auto& h=*static_cast<Host*>(raw);try{if(h.charge)h.charge(count);return 0;}catch(const std::exception& e){h.failure=std::current_exception();if(error&&capacity){const auto size=std::min<uint64_t>(capacity-1,std::strlen(e.what()));std::memcpy(error,e.what(),size);error[size]=0;}return 1;}catch(...){h.failure=std::current_exception();return 1;}}
};
const penta_dae_api_v2& api(const std::filesystem::path& path){const auto& a=runtime::detail::NativeModuleRegistry<penta_dae_api_v2>::get(path,"penta_dae_query_v2",PENTA_DAE_ABI_V2);if(!a.analyze||!a.linear_solve)throw Error(5,"DAE module lacks bounded higher-index/analysis capability.");return a;}
}
LinearModule::LinearModule(std::filesystem::path directory):path_(runtime::detail::nativeModulePath(std::move(directory),"penta_dae")){}
penta_dae_analyze_result_v2 LinearModule::analyze(const penta_dae_analyze_request_v2& q,const std::shared_ptr<std::atomic_bool>& cancellation,const std::function<void(std::size_t)>& charge)const{Host context{cancellation,charge,{}};const penta_dae_host_v1 host{sizeof(host),PENTA_DAE_ABI_V1,&context,Host::cancelled,Host::account};penta_dae_analyze_result_v2 result{};result.struct_size=sizeof(result);char error[2048]{};int status=0;runtime::ThreadBudget::instance().withReservation([&]{status=api(path_).analyze(&host,&q,&result,error,sizeof(error));});if(context.failure)std::rethrow_exception(context.failure);if(status)throw Error(Host::cancelled(&context)?3:status,error[0]?error:"Local DAE native analysis failed.");return result;}
LinearResult LinearModule::solve(const penta_linear_dae_request_v2& q,const std::shared_ptr<std::atomic_bool>& cancellation,const std::function<void(std::size_t)>& charge)const{if(!q.dimension||q.dimension>16||!std::isfinite(q.t0)||!std::isfinite(q.t1)||!std::isfinite(q.sample_step)||q.t1<=q.t0||q.sample_step<=0)throw Error(1,"Invalid bounded linear DAE dimensions/time.");const double count=std::ceil((q.t1-q.t0)/q.sample_step)+2;if(!std::isfinite(count)||count>1000000||count*(2*q.dimension+1)>8000000)throw Error(7,"Linear DAE retained output exceeds its coordinate budget.");const auto samples=static_cast<std::size_t>(count);const std::size_t n=q.dimension;LinearResult result;result.times.resize(samples);result.values.resize(samples*n);result.derivatives.resize(samples*n);result.initial.resize(n);result.initialDerivative.resize(n);result.freeBasis.resize(n*n);result.constraintProjector.resize(n*n);result.reducedMatrix.resize(n*n);auto& out=result.report;out.struct_size=sizeof(out);out.capacity=samples;out.times=result.times.data();out.values=result.values.data();out.derivatives=result.derivatives.data();out.consistent_initial=result.initial.data();out.consistent_derivative=result.initialDerivative.data();out.free_basis=result.freeBasis.data();out.constraint_projector=result.constraintProjector.data();out.reduced_matrix=result.reducedMatrix.data();out.matrix_capacity=n*n;Host context{cancellation,charge,{}};const penta_dae_host_v1 host{sizeof(host),PENTA_DAE_ABI_V1,&context,Host::cancelled,Host::account};char error[2048]{};int status=0;runtime::ThreadBudget::instance().withReservation([&]{status=api(path_).linear_solve(&host,&q,&out,error,sizeof(error));});if(context.failure)std::rethrow_exception(context.failure);if(status)throw Error(Host::cancelled(&context)?3:status,error[0]?error:"Native constant-pencil DAE solve failed.");result.times.resize(out.samples);result.values.resize(out.samples*n);result.derivatives.resize(out.samples*n);out.times=out.values=out.derivatives=out.consistent_initial=out.consistent_derivative=out.free_basis=out.constraint_projector=out.reduced_matrix=nullptr;return result;}
}
